import ast, copy, hashlib, importlib.util, json
from pathlib import Path
root=Path('/workspace')
files=['candidate.py','aligned_match.py','rotated_scaled_match.py','rotated_both_match.py']
ancestor=ast.parse((root/'history_g1_r0030_rotate_match_task.py').read_text())
aclass=next(n for n in ancestor.body if isinstance(n,ast.ClassDef))
old_methods={n.name:n for n in aclass.body if isinstance(n,ast.FunctionDef)}
normalized=[]
for file in files:
 text=(root/file).read_text(); tree=ast.parse(text); compile(text,file,'exec')
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef)); methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 init=methods['__init__']; defaults=dict(zip([n.arg for n in init.args.args][-len(init.args.defaults):],[ast.literal_eval(n) for n in init.args.defaults]))
 for key,val in config.items():
  got=defaults[key]; assert got==val or isinstance(got,tuple) and list(got)==val,(file,key,got,val)
 unchanged=set(methods)-{'__init__','_select_summary_alignment'}
 for method in unchanged: assert ast.dump(methods[method])==ast.dump(old_methods[method]),(file,method)
 def learned_tail(node):
  i=next(i for i,n in enumerate(node.body) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr=='embedding_layer' for t in n.targets))
  return ast.dump(ast.Module(body=node.body[i:],type_ignores=[]))
 assert learned_tail(init)==learned_tail(old_methods['__init__'])
 for n in ast.walk(tree):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   names=[n.module] if isinstance(n,ast.ImportFrom) else [a.name for a in n.names]
   assert all(x.split('.')[0] in {'torch','unirank'} for x in names)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','exec','eval','__import__','compile'}
 norm=copy.deepcopy(tree)
 for n in norm.body:
  if isinstance(n,ast.Expr) and isinstance(n.value,ast.Constant) and isinstance(n.value.value,str): n.value.value='DOC'
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets):
   for k,v in zip(n.value.keys,n.value.values):
    if ast.literal_eval(k)=='summary_rotation_group':v.value='SELECTOR'
 ncls=next(n for n in norm.body if isinstance(n,ast.ClassDef)); ni=next(n for n in ncls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 for arg,default in zip(ni.args.args[-len(ni.args.defaults):],ni.args.defaults):
  if arg.arg=='summary_rotation_group': default.value='SELECTOR'
 normalized.append(ast.dump(norm))
 select=methods['_select_summary_alignment']
 groups=ast.literal_eval(next(n.value for n in select.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='groups' for t in n.targets)))
 assert groups['raw_match']==(True,False,False,False,False)
 assert groups['scaled_match']==(False,False,False,False,True)
 assert groups['none']==(False,)*5 and groups['match']==(True,False,False,False,True)
 assert len(set(methods))==len(old_methods)
 print(file,hashlib.sha256(text.encode()).hexdigest(),'syntax/defaults/unchanged-methods/learned-tail/import-and-I-O-scan/selector PASS')
assert len(set(normalized))==1
print('Four sources identical modulo CONFIG and constructor selector: PASS')
print('Exact inherited methods:',len(unchanged),'of',len(methods))
print('Torch available:',importlib.util.find_spec('torch') is not None)
print('Dynamic checks and training: NOT RUN')
PY"

